## 代理模式与合约升级

代理模式是解决智能合约不可变性的核心方案。它将合约拆分为两部分：**代理合约**（Proxy）持有状态和地址，**实现合约**（Implementation）包含业务逻辑。代理通过 `delegatecall` 将调用转发给实现合约，升级时只需替换实现合约的地址。

三种主流代理模式各有适用场景：

| 代理模式          | 存储方式            | 升级机制             | 适用场景             |
| ----------------- | ------------------- | -------------------- | -------------------- |
| Transparent Proxy | 固定存储槽          | Admin 调用 upgrade   | 大型项目、明确管理员 |
| UUPS              | 固定存储槽          | 实现合约内置 upgrade | 省 Gas、更灵活       |
| Beacon Proxy      | Beacon 合约指向实现 | 一次升级影响所有实例 | 大量同类合约实例     |

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract UUPSProxy {
    bytes32 private constant IMPLEMENTATION_SLOT =
        bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);

    bytes32 private constant ADMIN_SLOT =
        bytes32(uint256(keccak256("eip1967.proxy.admin")) - 1);

    constructor(address implementation, bytes memory data) {
        _setImplementation(implementation);
        _setAdmin(msg.sender);
        if (data.length > 0) {
            (bool success, ) = implementation.delegatecall(data);
            require(success, "Init failed");
        }
    }

    fallback() external payable {
        address impl = _getImplementation();
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    receive() external payable {}

    function _getImplementation() internal view returns (address impl) {
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly {
            impl := sload(slot)
        }
    }

    function _setImplementation(address impl) internal {
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly {
            sstore(slot, impl)
        }
    }

    function _setAdmin(address admin) internal {
        bytes32 slot = ADMIN_SLOT;
        assembly {
            sstore(slot, admin)
        }
    }
}

abstract contract UUPSUpgradeable {
    bytes32 private constant IMPLEMENTATION_SLOT =
        bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);

    event Upgraded(address indexed implementation);

    function upgradeTo(address newImplementation) external virtual {
        _authorizeUpgrade(newImplementation);
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly {
            sstore(slot, newImplementation)
        }
        emit Upgraded(newImplementation);
    }

    function _authorizeUpgrade(address newImplementation) internal virtual;
}
```

