    B -->|delegatecall| C[Implementation V1]
    B -.->|升级后| D[Implementation V2]
    B --> E[Storage 状态保留]
```

## 工厂模式与克隆

工厂模式用于批量创建具有相同逻辑的合约实例。传统的 `new` 关键字部署成本高昂，EIP-1167 最小代理（Minimal Proxy，又称 Clone）通过复用已有合约代码将部署成本降低约 90%。

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

library Clones {
    function clone(address implementation) internal returns (address instance) {
        assembly {
            mstore(0x00, or(
                shr(0xe8, shl(0x60, implementation)),
                0x3d602d80600a3d3981f3363d3d373d3d3d363d73000000
            ))
            mstore(0x20, or(shl(0x78, implementation), 0x5af43d82803e903d91602b57fd5bf3))
            instance := create(0, 0x09, 0x37)
        }
        require(instance != address(0), "Clone failed");
    }

    function cloneDeterministic(
        address implementation,
        bytes32 salt
    ) internal returns (address instance) {
        assembly {
            mstore(0x00, or(
                shr(0xe8, shl(0x60, implementation)),
                0x3d602d80600a3d3981f3363d3d373d3d3d363d73000000
            ))
            mstore(0x20, or(shl(0x78, implementation), 0x5af43d82803e903d91602b57fd5bf3))
            instance := create2(0, 0x09, 0x37, salt)
        }
        require(instance != address(0), "Clone failed");
    }
}

contract VaultFactory {
    using Clones for address;

    address public immutable vaultImplementation;
    address[] public allVaults;

    event VaultCreated(address indexed vault, address indexed owner, uint256 index);

    constructor(address _implementation) {
        vaultImplementation = _implementation;
    }

    function createVault(bytes32 salt) external returns (address vault) {
        vault = vaultImplementation.cloneDeterministic(salt);

        IVault(vault).initialize(msg.sender);
        allVaults.push(vault);

        emit VaultCreated(vault, msg.sender, allVaults.length - 1);
    }

    function getVaultCount() external view returns (uint256) {
        return allVaults.length;
    }
}

interface IVault {
    function initialize(address owner) external;
}
```

使用 CREATE2 的确定性部署允许在合约部署前就计算出其地址，这对于跨链部署和反事实（Counterfactual）部署模式非常有用。

## 状态机与治理模式

状态机模式将合约的生命周期划分为明确的阶段，每个阶段只允许特定的操作。这在众筹、拍卖、投票等场景中广泛使用。

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract GovernorSimple {
    enum ProposalState { Pending, Active, Defeated, Succeeded, Executed }

    struct Proposal {
        address proposer;
        string description;
        uint256 forVotes;
        uint256 againstVotes;
        uint256 startBlock;
        uint256 endBlock;
        bool executed;
        mapping(address => bool) hasVoted;
    }

    uint256 public proposalCount;
    mapping(uint256 => Proposal) public proposals;
    mapping(address => uint256) public votingPower;

    uint256 public constant VOTING_PERIOD = 50400;
    uint256 public constant QUORUM = 1000e18;

    event ProposalCreated(uint256 indexed id, address proposer, string description);
    event VoteCast(uint256 indexed proposalId, address voter, bool support, uint256 weight);
    event ProposalExecuted(uint256 indexed id);

    function propose(string calldata description) external returns (uint256) {
        require(votingPower[msg.sender] > 0, "No voting power");

        uint256 proposalId = proposalCount++;
        Proposal storage p = proposals[proposalId];
        p.proposer = msg.sender;
        p.description = description;
        p.startBlock = block.number + 1;
        p.endBlock = block.number + VOTING_PERIOD;

        emit ProposalCreated(proposalId, msg.sender, description);
        return proposalId;
    }

    function castVote(uint256 proposalId, bool support) external {
        Proposal storage p = proposals[proposalId];
        require(state(proposalId) == ProposalState.Active, "Not active");
        require(!p.hasVoted[msg.sender], "Already voted");

        uint256 weight = votingPower[msg.sender];
        require(weight > 0, "No voting power");

        p.hasVoted[msg.sender] = true;

        if (support) {
            p.forVotes += weight;
        } else {
            p.againstVotes += weight;
        }

        emit VoteCast(proposalId, msg.sender, support, weight);
    }

    function state(uint256 proposalId) public view returns (ProposalState) {
        Proposal storage p = proposals[proposalId];
        if (p.executed) return ProposalState.Executed;
        if (block.number <= p.startBlock) return ProposalState.Pending;
        if (block.number <= p.endBlock) return ProposalState.Active;
        if (p.forVotes > p.againstVotes && p.forVotes >= QUORUM) {
            return ProposalState.Succeeded;
        }
        return ProposalState.Defeated;
    }
}
```

```mermaid
graph LR
    A[Pending 等待投票] -->|到达开始区块| B[Active 投票中]
    B -->|到达截止区块 + 通过| C[Succeeded 通过]
    B -->|到达截止区块 + 未通过| D[Defeated 未通过]
    C -->|执行| E[Executed 已执行]
```

治理合约通常还包含 Timelock 机制——提案通过后需要经过一段等待期才能执行，给社区提供退出窗口。Compound 和 OpenZeppelin 的 Governor 框架是当前最成熟的链上治理实现。

## Gas 优化模式

Gas 优化是合约设计中不可忽视的工程实践。以下是经过验证的优化模式：

| 优化技术             | 节省幅度        | 实现难度 | 适用场景         |
| -------------------- | --------------- | -------- | ---------------- |
| 紧凑存储布局         | 20-50% 存储成本 | 低       | 所有合约         |
| calldata 替代 memory | 10-30% 参数成本 | 低       | external 函数    |
| unchecked 算术       | 5-15% 计算成本  | 中       | 已验证安全的运算 |
| 批处理操作           | 30-60% 交易成本 | 中       | 批量转账/操作    |
| 位运算打包           | 40-70% 存储成本 | 高       | 多布尔值/小整数  |

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract GasOptimized {
    struct PackedData {
        uint128 amount;
        uint64 timestamp;
        uint32 nonce;
        bool active;
    }

    mapping(address => PackedData) public userData;

    error InsufficientBalance(uint256 available, uint256 required);
    error InvalidRecipient();

    function efficientTransfer(
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external {
        uint256 len = recipients.length;
        require(len == amounts.length, "Length mismatch");

        for (uint256 i; i < len; ) {
            address recipient = recipients[i];
            if (recipient == address(0)) revert InvalidRecipient();

            unchecked { ++i; }
        }
    }

    function packFlags(bool[8] calldata flags) external pure returns (uint8 packed) {
        for (uint256 i; i < 8; ) {
            if (flags[i]) {
                packed |= uint8(1 << i);
            }
            unchecked { ++i; }
        }
    }

    function unpackFlags(uint8 packed) external pure returns (bool[8] memory flags) {
        for (uint256 i; i < 8; ) {
            flags[i] = (packed & uint8(1 << i)) != 0;
            unchecked { ++i; }
        }
    }
}
```

